import json, os, glob, re, collections

root = os.path.expanduser("~/.claude/projects")
files = sorted(glob.glob(os.path.join(root, "*", "*.jsonl")), key=os.path.getmtime, reverse=True)[:50]

bash = collections.Counter()
mcp = collections.Counter()
bash_examples = collections.defaultdict(list)

ENV_RE = re.compile(r'^[A-Za-z_][A-Za-z0-9_]*=')

def lead(cmd):
    # split on pipes/&&/;/|| and take first segment
    seg = re.split(r'\|\||&&|[|;]', cmd)[0].strip()
    toks = seg.split()
    while toks and (ENV_RE.match(toks[0]) or toks[0] in ("sudo", "timeout", "command", "nohup")):
        toks.pop(0)
        if toks and toks[0].isdigit():
            toks.pop(0)
    if not toks:
        return None
    base = os.path.basename(toks[0])
    sub = toks[1] if len(toks) > 1 and not toks[1].startswith("-") else ""
    return (base, sub)

for f in files:
    try:
        for line in open(f, errors="replace"):
            if '"tool_use"' not in line:
                continue
            try:
                o = json.loads(line)
            except Exception:
                continue
            msg = o.get("message") or {}
            for c in (msg.get("content") or []):
                if not isinstance(c, dict) or c.get("type") != "tool_use":
                    continue
                n = c.get("name", "")
                if n == "Bash":
                    cmd = (c.get("input") or {}).get("command", "")
                    k = lead(cmd)
                    if k:
                        key = (k[0] + " " + k[1]).strip()
                        bash[key] += 1
                        if len(bash_examples[key]) < 3:
                            bash_examples[key].append(cmd[:120])
                elif n.startswith("mcp__"):
                    mcp[n] += 1
    except Exception:
        pass

print("### FILES SCANNED:", len(files))
print("\n### BASH (top 60)")
for k, v in bash.most_common(60):
    print(f"{v:5d}  {k}")
print("\n### MCP (top 60)")
for k, v in mcp.most_common(60):
    print(f"{v:5d}  {k}")
print("\n### EXAMPLES for selected")
for k in ["make", "uv", "python3", "kubectl", "gh", "npm", "pytest", "ruff"]:
    for kk in bash:
        if kk.split()[0] == k:
            print(f"-- {kk} ({bash[kk]}): {bash_examples[kk]}")

