import json, os, glob, re, collections

root = os.path.expanduser("~/.claude/projects")
files = sorted(glob.glob(os.path.join(root, "*", "*.jsonl")), key=os.path.getmtime, reverse=True)[:50]

bash = collections.Counter()
ENV_RE = re.compile(r'^[A-Za-z_][A-Za-z0-9_]*=')
SKIP = {"cd", "echo", "printf", "export", "set", "true", "false", "then", "else",
        "fi", "do", "done", "if", "for", "while", "source", "."}

def segments(cmd):
    # split on newlines, ;, &&, ||, | — good enough for frequency counting
    return re.split(r'\n|\|\||&&|[|;]', cmd)

def classify(seg):
    toks = seg.strip().split()
    while toks and (ENV_RE.match(toks[0]) or toks[0] in ("sudo", "timeout", "command", "nohup", "exec")):
        toks.pop(0)
        if toks and toks[0].isdigit():
            toks.pop(0)
    if not toks:
        return None
    base = os.path.basename(toks[0]).strip('"\'')
    if base in SKIP or not re.match(r'^[\w.-]+$', base):
        return None
    # find first non-flag arg as subcommand
    sub = ""
    for t in toks[1:]:
        if t.startswith("-"):
            continue
        if re.match(r'^[a-z][\w-]*$', t):
            sub = t
        break
    return (base + " " + sub).strip()

for f in files:
    try:
        for line in open(f, errors="replace"):
            if '"tool_use"' not in line:
                continue
            try:
                o = json.loads(line)
            except Exception:
                continue
            for c in ((o.get("message") or {}).get("content") or []):
                if not isinstance(c, dict) or c.get("type") != "tool_use" or c.get("name") != "Bash":
                    continue
                for seg in segments((c.get("input") or {}).get("command", "")):
                    k = classify(seg)
                    if k:
                        bash[k] += 1

print("### BASH by command+sub (count >= 3)")
for k, v in bash.most_common(80):
    if v >= 3:
        print(f"{v:5d}  {k}")

print("\n### BASH rolled up to base command")
base = collections.Counter()
for k, v in bash.items():
    base[k.split()[0]] += v
for k, v in base.most_common(35):
    print(f"{v:5d}  {k}")

