import json, os, glob, re, collections

root = os.path.expanduser("~/.claude/projects")
files = sorted(glob.glob(os.path.join(root, "*", "*.jsonl")), key=os.path.getmtime, reverse=True)[:50]

KUBE_FLAGS_WITH_VAL = {"--context", "--namespace", "-n", "--kubeconfig", "--cluster", "--user", "--as"}
counters = collections.defaultdict(collections.Counter)
examples = collections.defaultdict(list)

def sub_of(toks, flagset):
    i = 1
    while i < len(toks):
        t = toks[i]
        if t in flagset:
            i += 2
            continue
        if t.startswith("-"):
            if "=" in t:
                i += 1
                continue
            i += 1
            continue
        return t
    return ""

def segments(cmd):
    return re.split(r'\n|\|\||&&|[|;]', cmd)

TRACK = {"kubectl", "helm", "make", "uv", "pytest", "ruff", "mypy", "docker", "nerdctl", "flux", "curl", "awk", "dig", "npm", "yq"}

for f in files:
    try:
        for line in open(f, errors="replace"):
            if '"tool_use"' not in line:
                continue
            try:
                o = json.loads(line)
            except Exception:
                continue
            for c in ((o.get("message") or {}).get("content") or []):
                if not isinstance(c, dict) or c.get("type") != "tool_use" or c.get("name") != "Bash":
                    continue
                cmd = (c.get("input") or {}).get("command", "")
                for seg in segments(cmd):
                    toks = seg.strip().split()
                    while toks and (re.match(r'^[A-Za-z_][A-Za-z0-9_]*=', toks[0]) or toks[0] in ("sudo", "timeout")):
                        toks.pop(0)
                    if not toks:
                        continue
                    b = os.path.basename(toks[0]).strip('"\'')
                    if b not in TRACK:
                        continue
                    s = sub_of(toks, KUBE_FLAGS_WITH_VAL)
                    key = (b + " " + s).strip()
                    counters[b][key] += 1
                    if len(examples[key]) < 2:
                        examples[key].append(" ".join(toks)[:110])
    except Exception:
        pass

for b in ["kubectl", "helm", "make", "uv", "pytest", "ruff", "docker", "flux", "curl", "awk", "dig", "npm", "yq", "mypy"]:
    if not counters[b]:
        continue
    print(f"\n=== {b} (total {sum(counters[b].values())}) ===")
    for k, v in counters[b].most_common(22):
        ex = examples[k][0] if examples[k] else ""
        print(f"{v:5d}  {k:28s} | {ex}")

